const raw = $input.first().json.output;
const cleaned = raw.replace(/^```json\n/, '').replace(/\n```$/, '');
const parsed = JSON.parse(cleaned);
const actionType = parsed.action || 'query';
const subject = parsed.subject || 'Team Communication';
const context = parsed.context || '';
const urgency = parsed.urgency || 'medium';
const customMessage = parsed.customMessage || '';
const targets = parsed.targets || [];
const items = targets.map(target => ({ json: { ...target, actionType, subject, context, urgency, customMessage } }));
if (items.length === 0) { items.push({ json: { actionType, subject, context, urgency, customMessage, department: '', designation: '' } }); }
return items;

const results = $input.all();
const teamMembers = [];
for (const result of results) {
  if (result.json.document && result.json.document.fields) {
    const fields = result.json.document.fields;
    teamMembers.push({
      name: fields.name?.stringValue || 'N/A',
      email: fields.email?.stringValue || 'N/A',
      department: fields.department?.stringValue || 'N/A',
      designation: fields.designation?.stringValue || 'N/A',
      phone: fields.phone?.stringValue || 'N/A'
    });
  }
}
const response = {
  action: 'query_complete',
  totalMembers: teamMembers.length,
  members: teamMembers,
  message: teamMembers.length > 0 ? `Found ${teamMembers.length} team member(s)` : 'No team members found matching the criteria'
};
return [{ json: response }];

const emailResult = $('Send Email').item.json;
const teamMember = $('Get Team Member Details').item.json;
const queryData = $input.item.json;
const response = {
  action: 'email_sent',
  success: true,
  recipient: {
    name: teamMember.document?.fields?.name?.stringValue || 'Unknown',
    email: teamMember.document?.fields?.email?.stringValue || 'Unknown',
    department: queryData.department,
    designation: queryData.designation
  },
  subject: queryData.subject,
  context: queryData.context,
  urgency: queryData.urgency,
  emailId: emailResult.id || 'N/A',
  message: `Email successfully sent to ${teamMember.document?.fields?.name?.stringValue || 'team member'}`
};
return [{ json: response }];
